const raw = $json.choices?.[0]?.message?.content || $json.content || '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Could not parse JSON from Groq response:\n' + raw);
  parsed = JSON.parse(match[0]);
}
const target_roles = Array.isArray(parsed.target_roles) ? parsed.target_roles : [];
const skills = Array.isArray(parsed.skills) ? parsed.skills : [];
const search_keywords = Array.isArray(parsed.search_keywords) ? parsed.search_keywords : [];
const internship_keywords = Array.isArray(parsed.internship_keywords) ? parsed.internship_keywords : [];
const job_query = [...target_roles.map(r => `"${r}"`), ...search_keywords.map(s => `"${s}"`), "software engineer", "AI engineer", "machine learning engineer", "full stack developer", "python developer", "internship", "entry level"].filter(Boolean).join(" OR ");
const internship_query = internship_keywords.length ? internship_keywords.join(' OR ') : [...target_roles, 'intern'].filter(Boolean).join(' OR ');
return [{ json: { target_roles, skills, search_keywords, internship_keywords, job_query, internship_query, raw_ai_output: raw } }];

const jobs = $input.all().map(item => item.json);
const stage2 = $('Parse Resume Keywords').first().json;
const roleKeywords = [...(stage2.target_roles || []), ...(stage2.search_keywords || []), ...(stage2.internship_keywords || [])].map(k => String(k).toLowerCase().trim()).filter(Boolean);
const validJobs = jobs.filter(job => job && (job.position || job.company || job.description));
const filtered = validJobs.filter(job => {
  const haystack = [job.position || '', job.description || '', Array.isArray(job.tags) ? job.tags.join(' ') : ''].join(' ').toLowerCase();
  return roleKeywords.some(keyword => haystack.includes(keyword));
});
return filtered.map(job => ({ json: { title: job.position || '', company: job.company || '', url: job.url || '', location: job.location || 'Remote', type: 'Job', platform: 'RemoteOK', description: job.description || '' } }));

const input = $input.first().json;
const jobs = Array.isArray(input.data) ? input.data : [];
const stage2 = $('Parse Resume Keywords').first().json;
const roleKeywords = [...(stage2.target_roles || []), ...(stage2.search_keywords || []), ...(stage2.internship_keywords || [])].map(k => String(k).toLowerCase().trim()).filter(Boolean);
const filtered = jobs.filter(job => {
  const haystack = [job.title || '', job.description || '', Array.isArray(job.tags) ? job.tags.join(' ') : '', Array.isArray(job.job_types) ? job.job_types.join(' ') : ''].join(' ').toLowerCase();
  return roleKeywords.some(keyword => haystack.includes(keyword));
});
return filtered.map(job => ({ json: { title: job.title || '', company: job.company_name || '', url: job.url || '', location: Array.isArray(job.location) ? job.location.join(', ') : (job.location || ''), type: 'Job', platform: 'Arbeitnow', description: job.description || '' } }));

const html = $input.first().json.data || $input.first().json.body || $input.first().json.html || '';
if (!html || typeof html !== 'string') return [];
const clean = (s = '') => String(s).replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const includeKeywords = ['software','developer','development','web development','frontend','backend','full stack','react','javascript','node','python','django','fastapi','api','data science','data analyst','data analysis','machine learning','artificial intelligence','computer vision','deep learning','nlp','sql','database','automation','cloud','devops','software engineer','ai engineer','ml engineer'].map(k => k.toLowerCase());
const excludeKeywords = ['business development','sales','marketing','digital marketing','content writing','hr','human resources','operations','telecalling','customer support','recruitment','finance','accounting','law','graphic design','video editing'].map(k => k.toLowerCase());
const jobs = [];
const blocks = html.split('individual_internship').slice(1);
for (const rawBlock of blocks) {
  const block = 'individual_internship' + rawBlock.slice(0, 25000);
  const titleMatch = block.match(/job-title-href[^>]*title="([^"]+)"/i) || block.match(/job-title-href[^>]*>([\s\S]*?)<\/a>/i);
  const companyMatch = block.match(/company-name[^>]*>([\s\S]*?)<\/a>/i) || block.match(/company-name[^>]*>([\s\S]*?)<\/p>/i);
  const locationMatches = [...block.matchAll(/location_link[^>]*>([\s\S]*?)<\/a>/gi)];
  const stipendMatch = block.match(/stipend[^>]*>([\s\S]*?)<\/span>/i) || block.match(/stipend[^>]*>([\s\S]*?)<\/div>/i);
  const linkMatch = block.match(/href="(\/internship\/detail\/[^"]+)"/i);
  const title = clean(titleMatch ? titleMatch[1] : '');
  const company = clean(companyMatch ? companyMatch[1] : '');
  const location = locationMatches.length ? locationMatches.map(m => clean(m[1])).filter(Boolean).join(', ') : '';
  const stipend = clean(stipendMatch ? stipendMatch[1] : '');
  const relativeUrl = linkMatch ? linkMatch[1] : '';
  const url = relativeUrl ? `https://internshala.com${relativeUrl}` : '';
  if (!title || !company || !url) continue;
  const haystack = `${title} ${company} ${location} ${stipend}`.toLowerCase();
  if (excludeKeywords.some(keyword => haystack.includes(keyword))) continue;
  if (!includeKeywords.some(keyword => haystack.includes(keyword))) continue;
  jobs.push({ title, company, url, location, type: 'Internship', platform: 'Internshala', description: stipend });
}
const seen = new Set();
const uniqueJobs = jobs.filter(job => { if (seen.has(job.url)) return false; seen.add(job.url); return true; });
return uniqueJobs.map(job => ({ json: job }));

const data = $input.first().json;
const jobs = data.jobs_results || data.organic_results || [];
return jobs.map(job => ({ json: { title: job.title, company: job.company_name || job.company, location: job.location, url: job.link, platform: job.via, description: job.description } }));

const jobs = $input.all();
const cleanJobs = jobs.filter(j => j && j.json.title && j.json.url && j.json.title.length > 5).map(j => ({ json: { title: j.json.title, company: j.json.company || 'Unknown', location: j.json.location || 'Remote', url: j.json.url, platform: j.json.platform || 'Unknown', type: j.json.type || 'Job', description: (j.json.description || '').replace(/<[^>]*>/g, '').slice(0, 300) } }));
return cleanJobs;

const job = $json;
const skillsRaw = $node["Parse Resume Keywords"].json.skills;
const skills = Array.isArray(skillsRaw) ? skillsRaw.join(', ') : (skillsRaw || '');
const body = { model: "llama-3.3-70b-versatile", messages: [{ role: "system", content: "You are a job matching AI. Rate job relevance 0-10." }, { role: "user", content: `Rate this job from 0-10.
JOB:
Title: ${job.title || 'N/A'}
Company: ${job.company || 'N/A'}
Location: ${job.location || 'N/A'}
Description: ${job.description || 'N/A'}
Skills: ${skills}` }], temperature: 0.2 };
return [{ json: { ...job, body } }];

const items = $input.all();
return items.map(item => {
  const raw = item.json.choices?.[0]?.message?.content || '';
  let score = 5;
  const numMatch = raw.match(/(\d+(\.\d+)?)/); 
  if (numMatch) score = parseFloat(numMatch[1]);
  const reason = raw.replace(/\n/g, ' ').slice(0, 200);
  let priority = 'low';
  if (score >= 8) priority = 'high';
  else if (score >= 6) priority = 'medium';
  return { json: { title: item.json.title, company: item.json.company, url: item.json.url, location: item.json.location, type: item.json.type, platform: item.json.platform, description: item.json.description, ai_score: score, ai_reason: reason, apply_priority: priority } };
}).filter(item => (item.json.ai_score || 0) >= 1);

const jobs = $input.all();
const today = new Date().toLocaleDateString('en-IN', { day:'numeric', month:'long', year:'numeric' });
const high = jobs.filter(j => j.json.Priority === 'high');
const medium = jobs.filter(j => j.json.Priority === 'medium');
const low = jobs.filter(j => j.json.Priority === 'low');
const renderJobs = (list, color) => list.map(j => `<div style="border-left:4px solid ${color};padding:12px;margin:10px 0;background:#f9f9f9;border-radius:4px;"><b>${j.json.Title}</b> @ ${j.json.Company}<br/><small>${j.json.Platform} | ${j.json.Location} | ${j.json.Type}</small><br/><small>AI Score: <b>${j.json['AI Score']}/10</b> — ${j.json.Reason}</small><br/><a href="${j.json.Url}" style="color:#0077b5;">Apply →</a></div>`).join('');
const body = `<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;"><h2 style="background:#0077b5;color:white;padding:16px;border-radius:6px;">🎯 ${jobs.length} New Job Matches — ${today}</h2>${high.length ? `<h3 style="color:#e74c3c;">🔥 High Priority (${high.length})</h3>${renderJobs(high,'#e74c3c')}` : ''}${medium.length ? `<h3 style="color:#27ae60;">✅ Medium Priority (${medium.length})</h3>${renderJobs(medium,'#27ae60')}` : ''}${low.length ? `<h3 style="color:#3498db;">🔵 Low Priority (${low.length})</h3>${renderJobs(low,'#3498db')}` : ''}<hr/><p style="font-size:11px;color:#aaa;">n8n Job Search Automation</p></div>`;
return [{ json: { subject: `🎯 ${jobs.length} New Job Matches — ${today}`, body } }];
